function renderCockpit(){const d=data(),mapped=(d.valueStreams||[]).filter(s=>(d.subprocesses?.[s.id]||[]).length).length,open=(d.tasks||[]).filter(t=>!['Closed','Approved'].includes(t.status)),over=open.filter(t=>t.due&&t.due<today()).length;const heat=(d.valueStreams||[]).map(s=>{const p=(d.painPoints||[]).filter(x=>x.stream===s.id).length,r=(d.requirements||[]).filter(x=>x.stream===s.id).length,g=(d.fitGap||[]).filter(x=>x.stream===s.id).length;return `<tr data-open-stream="${s.id}"><td><b>${s.id}</b> · ${esc(s.name)}</td><td class="heat on">${(d.subprocesses?.[s.id]||[]).length||'—'}</td><td class="heat ${p?'on':''}">${p||'—'}</td><td class="heat ${r?'on':''}">${r||'—'}</td><td class="heat">Planned</td><td class="heat ${g?'on':''}">${g||'—'}</td><td class="heat">—</td><td class="heat">—</td><td class="heat">—</td></tr>`}).join('');return `<div class="page-head"><div><h1>Executive Cockpit</h1><p>As-Is → pain points → requirements → To-Be → fit/gap → build → test → readiness.</p></div>${badge(dirtyFiles.size?'Local changes pending':'GitHub baseline')}</div><div class="grid kpi">${kpi('As-Is mapped',`${mapped}/7`,'value streams')}${kpi('Process maps',flows.length,'Visio-derived')}${kpi('Pain points',(d.painPoints||[]).length,'current-state register')}${kpi('Open tasks',open.length,`${over} overdue`)}${kpi('Requirements',(d.requirements||[]).length,'traceability')}${kpi('Open decisions',(d.decisions||[]).filter(x=>x.status!=='Closed').length,'governance')}</div><div class="section-title"><h2>Enterprise value chain</h2><span>click a stream</span></div><div class="stream-strip">${(d.valueStreams||[]).map(s=>`<button class="card stream-card" data-open-stream="${s.id}"><div class="num">0${s.number}</div><h3>${esc(s.name)}</h3><div class="bpo">${esc(s.bpo)}</div>${badge(s.status)}</button>`).join('')}</div><div class="cross-strip">${(d.crossFunctional||[]).map(s=>`<button class="card stream-card compact" data-open-stream="${s.id}"><div class="num">Cross-functional</div><h3>${esc(s.name)}</h3><div class="bpo">${esc(s.bpo)}</div>${badge(s.status)}</button>`).join('')}</div><div class="section-title"><h2>Transformation heatmap</h2><span>process maturity by stream</span></div><div class="card table-wrap heatmap"><table class="data-table"><thead><tr><th>Value stream</th><th>As-Is</th><th>Pain points</th><th>Requirements</th><th>To-Be</th><th>Fit/Gap</th><th>Build</th><th>Testing</th><th>Readiness</th></tr></thead><tbody>${heat}</tbody></table></div>`}
function renderStreams(){const d=data(),s=allStreams().find(x=>x.id===selectedStream)||allStreams()[0];if(!s)return'<div class="empty">No streams loaded.</div>';selectedStream=s.id;const ps=d.subprocesses?.[s.id]||[],fs=streamFlows(s.id);const tabs=['overview','asis','pain','requirements','team','tasks'];return `<div class="stream-selector">${allStreams().map(x=>`<button class="${x.id===s.id?'active':''}" data-open-stream="${x.id}"><b>${x.id}</b> · ${esc(x.name)}<span>${esc(x.bpo||'')}</span></button>`).join('')}</div><div class="stream-header"><div><h1>${s.id} · ${esc(s.name)}</h1><p class="small-note">${esc(s.source_status||'Cross-functional framework')}</p></div><div class="meta"><div class="meta-box"><div class="k">BPO</div><div class="v">${esc(s.bpo||'TBD')}</div></div><div class="meta-box"><div class="k">As-Is maps</div><div class="v">${fs.length}</div></div></div></div><div class="tabs">${tabs.map(t=>`<button data-stream-tab="${t}" class="${streamTab===t?'active':''}">${({overview:'Overview',asis:'As-Is',pain:'Pain Points',requirements:'Requirements',team:'BPO / SMEs',tasks:'Tasks'})[t]}</button>`).join('')}</div>${streamTab==='overview'?streamOverview(s,ps,fs):streamTab==='asis'?streamAsIs(s,ps,fs):streamTab==='pain'?streamPain(s):streamTab==='requirements'?streamRequirements(s):streamTab==='team'?streamTeam(s):streamTasks(s)}`}
function streamOverview(s,ps,fs){const d=data();return `<div class="grid two-col"><div class="card pad"><h3>Enterprise L2 capabilities</h3><div class="chip-row">${(s.l2||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="section-title"><h2>Imported current-state maps</h2><span>${ps.length}</span></div>${ps.map(p=>`<button class="process-row" data-open-flow="${p.flowId}"><div><b>${esc(p.id)} · ${esc(p.name)}</b><small>${esc((p.systems||[]).join(' · '))}</small></div>${badge(p.status)}</button>`).join('')||'<div class="empty">No dedicated Visio map in the supplied package.</div>'}</div><div class="card pad"><h3>Governance snapshot</h3><div class="grid two-col">${kpi('Pain points',(d.painPoints||[]).filter(x=>x.stream===s.id).length,'current state')}${kpi('Opportunities',(d.opportunities||[]).filter(x=>x.stream===s.id).length,'identified')}${kpi('Requirements',(d.requirements||[]).filter(x=>x.stream===s.id).length,'defined')}${kpi('Tasks',(d.tasks||[]).filter(x=>x.stream===s.id).length,'execution')}</div><div class="section-title"><h2>Source coverage</h2></div><p class="small-note">Legacy process IDs are retained while the maps are normalized to the enterprise value-stream structure.</p></div></div>`}
function streamAsIs(s,ps,fs){if(!fs.length)return `<div class="card empty">No Visio-derived As-Is flow is mapped to ${esc(s.id)} yet.</div>`;if(!selectedFlowId||!fs.some(f=>f.id===selectedFlowId))selectedFlowId=fs[0].id;const f=flowFor(selectedFlowId),p=ps.find(x=>x.flowId===f.id)||{};return `<div class="asis-toolbar"><select id="flowSelect">${fs.map(x=>`<option value="${x.id}" ${x.id===f.id?'selected':''}>${esc(x.legacyId?x.legacyId+' · ':'')}${esc(x.processName||x.title)}</option>`).join('')}</select><div><button class="btn ${asIsMode==='text'?'primary':''}" data-asis="text">Process text</button><button class="btn ${asIsMode==='flow'?'primary':''}" data-asis="flow">Flow chart</button></div><button class="btn" id="editProcess">Edit process</button></div>${asIsMode==='flow'?flowEditorHtml(f):processText(p,f)}`}
function processText(p,f){const a=f.nodes.filter(n=>n.type==='activity');return `<div class="grid asis-grid"><div class="card pad"><h3>${esc(p.id||f.legacyId)} · ${esc(p.name||f.processName)}</h3><div class="detail-grid"><label>Status<span>${badge(p.status||f.status)}</span></label><label>Version<span>${esc(f.version||'')}</span></label><label>Systems<span>${esc((f.systems||[]).join(', ')||'—')}</span></label><label>Source<span>${esc(p.source||'Visio current-state map')}</span></label></div><div class="section-title"><h2>Activities</h2><span>${a.length}${f.simplifiedFromVisio?` shown / ${f.sourceNodeCount} source nodes`:''}</span></div><ol class="activity-list">${a.map(n=>`<li data-edit-node="${n.id}"><b>${esc(n.label)}</b>${n.system?`<small>${esc(n.system)}</small>`:''}</li>`).join('')}</ol></div><div class="card pad"><h3>Process intelligence</h3><div class="intelligence-grid">${kpi('Activities',a.length,'working view')}${kpi('Systems',(f.systems||[]).length,'identified')}${kpi('Connections',f.edges.length,'working view')}${kpi('Source nodes',f.sourceNodeCount||f.nodes.length,'Visio extraction')}</div>${f.simplifiedFromVisio?'<div class="notice warning">This detailed Visio was simplified into a connected editable working view. The source node/connector counts remain recorded for traceability.</div>':''}</div></div>`}
function flowEditorHtml(f){return `<div class="flow-tools"><button class="btn" id="addActivity">+ Activity</button><button class="btn" id="addDecision">+ Decision</button><button class="btn" id="connectNode" ${selectedNodeId?'':'disabled'}>Connect from selected</button><button class="btn" id="editNode" ${selectedNodeId?'':'disabled'}>Edit selected</button><button class="btn danger" id="deleteNode" ${selectedNodeId?'':'disabled'}>Delete selected</button><span>${f.nodes.length} nodes · ${f.edges.length} connectors</span></div><div class="flow-scroll"><div id="flowCanvas" class="flow-canvas"><svg class="flow-lines" viewBox="0 0 1200 720"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#7186a8"/></marker></defs>${f.edges.map(e=>edgeSvg(f,e)).join('')}</svg>${f.nodes.map(n=>`<div class="flow-node ${n.type||'activity'} ${n.id===selectedNodeId?'selected':''}" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><strong>${esc(n.label)}</strong>${n.system?`<small>${esc(n.system)}</small>`:''}</div>`).join('')}</div></div>`}
function edgeSvg(f,e){const a=f.nodes.find(n=>n.id===e.from),b=f.nodes.find(n=>n.id===e.to);return a&&b?`<line x1="${a.x+72}" y1="${a.y+29}" x2="${b.x+72}" y2="${b.y+29}" marker-end="url(#arr)"/>`:''}
function streamPain(s){const d=data(),items=[...(d.painPoints||[]).filter(x=>x.stream===s.id).map(x=>({...x,_kind:'Pain point'})),...(d.opportunities||[]).filter(x=>x.stream===s.id).map(x=>({...x,_kind:'Opportunity'}))];return `<div class="section-title"><h2>Current-state issues & opportunities</h2><button class="btn primary" id="addPain">+ Add item</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Type</th><th>Legacy subprocess</th><th>Description</th><th>Impact</th><th>Phasing</th><th>Status</th></tr></thead><tbody>${items.map(x=>`<tr data-edit-pain="${x.id}" data-kind="${x._kind}"><td>${esc(x.id)}</td><td>${esc(x._kind)}</td><td>${esc(x.subprocess)}</td><td>${esc(x.title)}</td><td>${badge(x.impact)}</td><td>${esc(x.phase)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
function streamRequirements(s){const r=(data().requirements||[]).filter(x=>x.stream===s.id);return `<div class="section-title"><h2>Requirements traceability</h2><button class="btn primary" id="addReq">+ Requirement</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Requirement</th><th>Pain point</th><th>Fit / Gap</th><th>Owner</th><th>Status</th></tr></thead><tbody>${r.map(x=>`<tr data-edit-req="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.title)}</td><td>${esc(x.painPoint||'')}</td><td>${esc(x.fitGap||'TBD')}</td><td>${esc(x.owner||'')}</td><td>${esc(x.status||'Draft')}</td></tr>`).join('')}</tbody></table>${r.length?'':'<div class="empty">No requirements entered yet.</div>'}</div>`}
function personResponsibilities(p){const d=data();return p.role==='BPO'?(d.bpoResponsibilities||[]):(d.smeTemplateResponsibilities||[])}
function personCard(p){const rs=p.responsibilities||personResponsibilities(p);return `<div class="card person-card" data-edit-person="${p.id}"><div class="role-tag">${esc(p.role)}</div><h3>${esc(p.name)}</h3><div class="role">${esc(p.stream)} · ${esc(allStreams().find(s=>s.id===p.stream)?.name||'')}</div><ul>${rs.slice(0,7).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="load"><span style="width:${Math.min(100,p.capacityPct||0)}%"></span></div><small>${p.capacityPct||0}% planned project capacity</small></div>`}
function streamTeam(s){const ps=(data().people||[]).filter(p=>p.stream===s.id);return `<div class="section-title"><h2>BPO & SME workspace</h2><button class="btn primary" id="addPerson">+ Add SME</button></div><div class="grid three-col">${ps.map(personCard).join('')}</div>`}
function streamTasks(s){return taskTable((data().tasks||[]).filter(t=>t.stream===s.id),true)}
function renderPeople(){const d=data();return `<div class="page-head"><div><h1>People & Ownership</h1><p>BPO and SME responsibilities, process coverage and project capacity.</p></div><button class="btn primary" id="addPersonGlobal">+ SME</button></div><div class="grid three-col">${(d.people||[]).map(personCard).join('')}</div>`}
function taskTable(ts,compact=false){return `<div class="section-title"><h2>${compact?'Value-stream tasks':'Task Control Tower'}</h2><button class="btn primary" id="addTask">+ Task</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Task</th><th>Stream</th><th>Owner</th><th>Priority</th><th>Status</th><th>Due</th></tr></thead><tbody>${ts.map(t=>`<tr data-edit-task="${t.id}"><td>${esc(t.id)}</td><td>${esc(t.title)}</td><td>${esc(t.stream)}</td><td>${esc(t.owner)}</td><td>${badge(t.priority)}</td><td><select class="status-select" data-task-status="${t.id}">${['Not Started','In Progress','Waiting','Ready for Review','BPO Review','Approved','Closed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${esc(t.due||'')}</td></tr>`).join('')}</tbody></table></div>`}
function renderExecution(){const d=data(),ts=d.tasks||[];return `<div class="page-head"><div><h1>Execution Control</h1><p>Task status, ownership, dependencies and schedule.</p></div></div>${taskTable(ts)}<div class="section-title"><h2>Task Gantt</h2></div>${gantt(ts.map(t=>({name:t.title,stream:t.stream,start:t.start,end:t.due,status:t.status})))}`}
function renderGovernance(){const d=data();return `<div class="page-head"><div><h1>Governance & Traceability</h1><p>Pain point → requirement → fit/gap → decision.</p></div><button class="btn primary" id="addDecision">+ Decision</button></div><div class="grid kpi">${kpi('Pain points',(d.painPoints||[]).length,'current state')}${kpi('Opportunities',(d.opportunities||[]).length,'current state')}${kpi('Requirements',(d.requirements||[]).length,'defined')}${kpi('Fit / Gap',(d.fitGap||[]).length,'classified')}${kpi('Decisions',(d.decisions||[]).length,'register')}${kpi('Sources',(d.sources||[]).length,'baseline')}</div><div class="section-title"><h2>Decision register</h2></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Decision</th><th>Stream</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody>${(d.decisions||[]).map(x=>`<tr data-edit-decision="${x.id}"><td>${esc(x.id)}</td><td>${esc(x.title)}</td><td>${esc(x.stream)}</td><td>${esc(x.owner)}</td><td>${esc(x.due||'')}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table>${(d.decisions||[]).length?'':'<div class="empty">No decisions entered yet.</div>'}</div>`}
function gantt(items){const dates=items.flatMap(x=>[x.start,x.end]).filter(Boolean).map(x=>new Date(x+'T00:00:00'));if(!dates.length)return'<div class="card empty">No dated items.</div>';const min=new Date(Math.min(...dates)),max=new Date(Math.max(...dates)),span=Math.max(1,max-min);return `<div class="card gantt"><div class="gantt-head"><span>${min.toLocaleDateString()}</span><span>${max.toLocaleDateString()}</span></div>${items.filter(x=>x.start&&x.end).map(x=>{const a=new Date(x.start+'T00:00:00'),b=new Date(x.end+'T00:00:00'),left=100*(a-min)/span,width=Math.max(1,100*(b-a)/span);return `<div class="gantt-row"><div class="gantt-label"><b>${esc(x.name)}</b><small>${esc(x.stream||'')} · ${esc(x.status||'')}</small></div><div class="gantt-track"><div class="gantt-bar" style="left:${left}%;width:${width}%"></div></div></div>`}).join('')}</div>`}
function renderRoadmap(){const m=data().milestones||[];return `<div class="page-head"><div><h1>Program Roadmap</h1><p>Draft 18-month implementation schedule. Dates are planning assumptions and remain editable.</p></div><button class="btn primary" id="addMilestone">+ Milestone</button></div>${gantt(m)}<div class="section-title"><h2>Milestones</h2></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Milestone</th><th>Stream</th><th>Start</th><th>End</th><th>Status</th></tr></thead><tbody>${m.map(x=>`<tr data-edit-milestone="${x.id}"><td>${esc(x.name)}</td><td>${esc(x.stream)}</td><td>${esc(x.start)}</td><td>${esc(x.end)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
